import React, { useState, useEffect } from 'react'
import classnames from 'classnames'
import { fbt } from 'fbt-runtime'
import { useWeb3React } from '@web3-react/core'

import withLoginModal from 'hoc/withLoginModal'
import mixpanel from 'utils/mixpanel'

const GetOUSD = ({
  className,
  style,
  dark,
  light,
  primary,
  showLogin,
  trackSource,
  light2,
  zIndex2,
}) => {
  const { active } = useWeb3React()
  const [userAlreadyConnectedWallet, setUserAlreadyConnectedWallet] = useState(
    false
  )

  useEffect(() => {
    if (!userAlreadyConnectedWallet && localStorage.getItem('userConnectedWallet')) {
      setUserAlreadyConnectedWallet(true)
    }

    if (active) {
      localStorage.setItem('userConnectedWallet', 'true')
      setUserAlreadyConnectedWallet(true)
    }
  }, [active])

  const classList = classnames(
    'btn d-flex align-items-center justify-content-center',
    className,
    dark && 'btn-dark',
    light && 'btn-light',
    light2 && 'btn-light2',
    primary && 'btn-primary',
    zIndex2 && 'zIndex2'
  )

  return (
    <>
      <button
        className={classList}
        style={style}
        onClick={() => {
          mixpanel.track('Get OUSD', {
            source: trackSource,
          })
          if (showLogin) showLogin()
        }}
      >
        {!userAlreadyConnectedWallet
          ? fbt('Get OUSD', 'Get OUSD button')
          : fbt('Connect', 'Connect')}
      </button>

