        let startVal = animAmount || 0
        let endVal = newAmount

        const reverseOrder = animAmount > newAmount

        if (reverseOrder) {
          endVal = animAmount
          startVal = newAmount
        }

        animateCancel = animateValue({
          from: startVal,
          to: endVal,
          callbackValue: (val) => {
            let adjustedValue
